def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    class Point:
        def __init__(self, *args, **kwargs):
            self.fields = fields
            self.srid_map = srid_map
            self.values = {}
            for field in fields:
                if field in kwargs:
                    self.values[field] = kwargs[field]
                elif len(args) > 0:
                    self.values[field] = args.pop(0)
                else:
                    self.values[field] = None
        def __repr__(self):
            return f"{name}({', '.join(f'{k}={v}' for k, v in self.values.items())})"
    Point.__name__ = name
