def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if style == "pep440":
        rendered = pieces["closest-tag"]
        if pieces["distance"] or pieces["dirty"]:
            rendered += ".post%d" % pieces["distance"]
            if pieces["dirty"]:
                rendered += ".dev0"
            rendered += "+" + pieces["date"]
        return rendered
    elif style == "git-describe":
        rendered = pieces["closest-tag"]
        if pieces["distance"] or pieces["dirty"]:
            rendered += "-%d-g%s" % (pieces["distance"], pieces["short"])
            if pieces["dirty"]:
                rendered += ".dirty"
        return rendered
    elif style == "short":
        rendered = pieces["closest-tag"]
        if pieces["distance"] or pieces["dirty"]:
            rendered += "-%d" % pieces["distance"]
            if pieces["dirty"]:
                rendered += ".dirty"
        return rendered
    elif style == "tagged":
        rendered = pieces["closest-tag"]
        if pieces["distance"] or pieces["dirty"]:
            rendered += "-%d" % pieces["distance"]
            if pieces["dirty"]:
                rendered += ".dirty"
        return rendered
    elif style == "tagged-date":
        rendered = pieces["closest-tag"]
        if pieces["distance"] or pieces["dirty"]:
            rendered += "-%d" % pieces["distance"]
            if pieces["dirty"]:
                rendered += ".dirty"
        rendered += "-" + pieces["date"]
        return rendered
    else:
        raise ValueError("unknown style '%s'" % style)
