def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, str):
        commands = [commands]
    if isinstance(args, str):
        args = [args]
    if not isinstance(commands, list):
        raise TypeError("commands must be a string or a list of strings")
    if not isinstance(args, list):
        raise TypeError("args must be a list of strings")

    full_command = commands + args
    if verbose:
        print("Running command: " + " ".join(full_command))

    try:
        if hide_stderr:
            result = subprocess.run(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
        else:
            result = subprocess.run(full_command, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        return result
    except Exception as e:
        if verbose:
