def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Try to parse as JSON first
    try:
        data = json.loads(document)
        # Check if it's a valid webfinger JSON response
        if "subject" in data and "links" in data:
            return data
    except json.JSONDecodeError:
        pass

    # Try to parse as XRD (XML)
    try:
        root = ET.fromstring(document)
        # XRD format: <XRD xmlns="http://docs.oasis-open.org/ns/xri/xrd-1.0">
        # We need to handle namespaces
        ns = {'xrd': 'http://docs.oasis-open.org/ns/xri/xrd-1.0'}

        # Extract subject
        subject_elem = root.find('xrd:Subject', ns)
        if subject_elem is None:
            # Try without namespace
            subject_elem = root.find('Subject')

        subject = subject_elem.text if subject_elem is not None else ""

        # Extract links
        links = []
        alias_elems = root.findall('xrd:Alias', ns)
        if not alias_elems:
            alias_elems = root.findall('Alias')

        for alias in alias_elems:
            link = {
                "rel": alias.get("rel", ""),
                "href": alias.text if alias.text else "",
                "type": alias.get("type", "")
            }
            links.append(link)

        return {
            "subject": subject,
            "links": links
        }
    except ET.ParseError:
        pass

    # If neither format could be parsed, return an empty dict or raise an error
    return {}
```

