def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    import requests
    import json

    # Construct the webfinger URL
    # The handle is expected to be in the format "user@domain"
    if "@" not in handle:
        return None

    user, domain = handle.split("@", 1)

    # The webfinger URL is typically:
    # https://domain/.well-known/webfinger?resource=acct:user@domain
    url = f"https://{domain}/.well-known/webfinger"
    params = {
        "resource": f"acct:{user}@{domain}"
    }

    try:
        response = requests.get(url, params=params, timeout=10)
        if response.status_code == 200:
            # Try to parse as JSON
            try:
                data = response.json()
                return json.dumps(data)
            except json.JSONDecodeError:
                # If it's not valid JSON, return the text content
                return response.text
        else:
            return None
    except Exception:
        # Catch all exceptions and return None
        return None
